mapper.select:
SELECT inq_id, product_id, package_id, member_id, inq_content, inq_status, answer_content, answered_by, answered_at, created_at, updated_at, is_secret, is_deleted FROM PRODUCT_INQ WHERE product_id = #{productId} AND is_deleted = 'N'
AND inq_status = #{inqStatus}
ORDER BY created_at DESC, inq_id DESC LIMIT #{limit} OFFSET #{offset}
